namespace RecipeSharing.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeSharing.Models;

namespace RecipeSharing.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute.\n5. Bake for 10-12 minutes.\n6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Cumin, Tomato sauce, Heavy cream, Garlic, Ginger, Onion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices.\n5. Simmer 20 minutes, add cream.\n6. Add chicken and cook 10 more minutes.", AverageRating = 4.8, RatingCount = 24 },
        new Recipe { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco seasoning, Corn tortillas, Lettuce, Tomato, Cheese, Sour cream, Salsa", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water.\n3. Simmer until thickened.\n4. Warm tortillas.\n5. Assemble tacos with toppings.", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Lime, Fish sauce, Tamarind paste, Sugar, Garlic", Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Stir-fry shrimp and garlic.\n3. Push aside, scramble eggs.\n4. Add noodles and sauce (tamarind, fish sauce, sugar).\n5. Toss with bean sprouts.\n6. Serve with peanuts and lime.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 5, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, add egg mixture.\n6. Toss vigorously until creamy.", AverageRating = 4.7, RatingCount = 19 },
        new Recipe { Id = 6, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter, Sugar, Brown sugar, Eggs, Vanilla, Flour, Baking soda, Salt, Chocolate chips", Steps = "1. Cream butter and sugars.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt.\n4. Combine wet and dry ingredients.\n5. Fold in chocolate chips.\n6. Bake at 375°F for 9-11 minutes.", AverageRating = 4.9, RatingCount = 31 },
        new Recipe { Id = 7, Title = "Miso Soup", Category = "Japanese", Ingredients = "Dashi stock, White miso paste, Tofu, Wakame seaweed, Green onions", Steps = "1. Heat dashi stock until simmering.\n2. Dissolve miso paste in a ladleful of stock.\n3. Add dissolved miso back to pot.\n4. Add cubed tofu and wakame.\n5. Heat gently (do not boil).\n6. Serve topped with green onions.", AverageRating = 4.3, RatingCount = 7 },
        new Recipe { Id = 8, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in lime juice and salt.\n4. Fold in diced onion, tomato, jalapeño.\n5. Top with cilantro.\n6. Serve immediately with chips.", AverageRating = 4.4, RatingCount = 11 },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetRecipeById(recipeId);
        if (recipe == null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = Math.Round(_ratings[recipeId].Average(), 1);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

