toolArgs.file_text:
@page "/submit"
@using RecipeSharing.Services
@using RecipeSharing.Models
@inject RecipeService RecipeService
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage != null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="newRecipe" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="newRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => newRecipe.Title" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="newRecipe.Category">
            <option value="">-- Select a category --</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => newRecipe.Category" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="newRecipe.Ingredients"
            placeholder="List ingredients, one per line or comma-separated" />
        <ValidationMessage For="() => newRecipe.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="newRecipe.Steps"
            placeholder="Describe the preparation steps" />
        <ValidationMessage For="() => newRecipe.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private Recipe newRecipe = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(newRecipe.Title) ||
            string.IsNullOrWhiteSpace(newRecipe.Category) ||
            string.IsNullOrWhiteSpace(newRecipe.Ingredients) ||
            string.IsNullOrWhiteSpace(newRecipe.Steps))
        {
            return;
        }

        RecipeService.AddRecipe(newRecipe);
        successMessage = $"Recipe \"{newRecipe.Title}\" submitted successfully!";
        newRecipe = new();
    }
}
